+import Yoga, {type Node as YogaNode} from 'yoga-layout';
+import {type DOMElement, type DOMNode} from './dom.js';
+import {type Styles} from './styles.js';
+
+type Track =
+	| {kind: 'fixed'; size: number}
+	| {kind: 'fr'; factor: number; min: number}
+	| {kind: 'auto'};
+
+type Placement = {start: number; end: number};
+
+const trackPattern = /minmax\\(\\s*[^,]+\\s*,\\s*[^)]+\\s*\\)|\\S+/g;
+
+const parseTrack = (value: string): Track => {
+	const minmax = /^minmax\\(\\s*(\\d+(?:\\.\\d+)?)\\s*,\\s*(\\d+(?:\\.\\d+)?(?:fr)?)\\s*\\)$/.exec(value);
+	if (minmax) {
+		const min = Number(minmax[1]);
+		const max = minmax[2]!;
+		if (max.endsWith('fr')) {
+			return {kind: 'fr', factor: Number.parseFloat(max), min};
+		}
+
+		return {kind: 'fixed', size: Number(max)};
+	}
+
+	if (value === 'auto') {
+		return {kind: 'auto'};
+	}
+
+	if (value.endsWith('fr')) {
+		return {kind: 'fr', factor: Number.parseFloat(value) || 1, min: 0};
+	}
+
+	const size = Number(value);
+	return Number.isFinite(size) && size >= 0 ? {kind: 'fixed', size} : {kind: 'auto'};
+};
+
+const parseTracks = (value: string | undefined): Track[] =>
+	value?.match(trackPattern)?.map(parseTrack) ?? [];
+
+const parsePlacement = (value: number | string | undefined): Placement | undefined => {
+	if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
+		return {start: value - 1, end: value};
+	}
+
+	if (typeof value === 'string') {
+		const match = /^(\\d+)\\s*\\/\\s*(\\d+)$/.exec(value);
+		if (match && Number(match[1]) > 0 && Number(match[2]) > Number(match[1])) {
+			return {start: Number(match[1]) - 1, end: Number(match[2]) - 1};
+		}
+	}
+};
+
+const restoreNode = (node: YogaNode, style: Styles): void => {
+	node.setPositionType(
+		style.position === 'absolute'
+			? Yoga.POSITION_TYPE_ABSOLUTE
+			: style.position === 'static'
+				? Yoga.POSITION_TYPE_STATIC
+				: Yoga.POSITION_TYPE_RELATIVE,
+	);
+	node.setPositionAuto(Yoga.EDGE_LEFT);
+	node.setPositionAuto(Yoga.EDGE_TOP);
+
+	if (typeof style.width === 'number') node.setWidth(style.width);
+	else if (typeof style.width === 'string') node.setWidthPercent(Number.parseFloat(style.width));
+	else node.setWidthAuto();
+
+	if (typeof style.height === 'number') node.setHeight(style.height);
+	else if (typeof style.height === 'string') node.setHeightPercent(Number.parseFloat(style.height));
+	else node.setHeightAuto();
+};
+
+/** Restores grid-managed Yoga nodes before a new Yoga layout pass. */
+export const resetGridLayout = (node: DOMNode): void => {
+	if (node.yogaNode) restoreNode(node.yogaNode, node.style);
+	if ('childNodes' in node) {
+		for (const child of node.childNodes) resetGridLayout(child);
+	}
+};
+
+const gapFor = (style: Styles, axis: 'column' | 'row'): number =>
+	(axis === 'column' ? style.columnGap : style.rowGap) ?? style.gap ?? 0;
+
+const resolveTracks = (tracks: Track[], available: number, gap: number, autoSizes: number[]): number[] => {
+	const sizes = tracks.map((track, index) =>
+		track.kind === 'fixed' ? track.size : track.kind === 'auto' ? (autoSizes[index] ?? 0) : track.min,
+	);
+	const used = sizes.reduce((total, size) => total + size, 0) + Math.max(0, tracks.length - 1) * gap;
+	const frTotal = tracks.reduce((total, track) => total + (track.kind === 'fr' ? track.factor : 0), 0);
+	if (frTotal > 0 && available > used) {
+		const remaining = available - used;
+		for (const [index, track] of tracks.entries()) {
+			if (track.kind === 'fr') sizes[index]! += (remaining * track.factor) / frTotal;
+		}
+	}
+
+	return sizes;
+};
+
+const findPlacement = (occupied: Set<string>, columns: number, column: Placement | undefined, row: Placement | undefined): {column: Placement; row: Placement} => {
+	const columnSpan = column ? column.end - column.start : 1;
+	const rowSpan = row ? row.end - row.start : 1;
+	for (let rowStart = row?.start ?? 0; ; rowStart++) {
+		for (let columnStart = column?.start ?? 0; columnStart <= columns - columnSpan; columnStart++) {
+			const candidate = {column: column ?? {start: columnStart, end: columnStart + columnSpan}, row: row ?? {start: rowStart, end: rowStart + rowSpan}};
+			let free = true;
+			for (let y = candidate.row.start; y < candidate.row.end; y++) for (let x = candidate.column.start; x < candidate.column.end; x++) free &&= !occupied.has(`${x}:${y}`);
+			if (free) return candidate;
+			if (column) break;
+		}
+		if (row) break;
+	}
+
+	return {column: column ?? {start: 0, end: 1}, row: row ?? {start: 0, end: 1}};
+};
+
+const layoutGrid = (node: DOMElement): void => {
+	if (node.style.display !== 'grid' || !node.yogaNode) return;
+	const columns = parseTracks(node.style.gridTemplateColumns);
+	if (columns.length === 0) columns.push({kind: 'auto'});
+	const rows = parseTracks(node.style.gridTemplateRows);
+	const children = node.childNodes.filter((child): child is DOMElement => Boolean(child.yogaNode));
+	const occupied = new Set<string>();
+	const placements = children.map(child => {
+		const placement = findPlacement(occupied, columns.length, parsePlacement(child.style.gridColumn), parsePlacement(child.style.gridRow));
+		for (let y = placement.row.start; y < placement.row.end; y++) for (let x = placement.column.start; x < placement.column.end; x++) occupied.add(`${x}:${y}`);
+		return {child, ...placement};
+	});
+	const rowCount = Math.max(rows.length, ...placements.map(item => item.row.end), 0);
+	while (rows.length < rowCount) rows.push({kind: 'auto'});
+	const columnAutoSizes = columns.map(() => 0);
+	const rowAutoSizes = rows.map(() => 0);
+	for (const item of placements) {
+		const layout = item.child.yogaNode!.getComputedLayout();
+		if (item.column.end - item.column.start === 1 && columns[item.column.start]?.kind === 'auto') columnAutoSizes[item.column.start] = Math.max(columnAutoSizes[item.column.start]!, layout.width);
+		if (item.row.end - item.row.start === 1 && rows[item.row.start]?.kind === 'auto') rowAutoSizes[item.row.start] = Math.max(rowAutoSizes[item.row.start]!, layout.height);
+	}
+	const columnGap = gapFor(node.style, 'column');
+	const rowGap = gapFor(node.style, 'row');
+	const contentWidth = node.yogaNode.getComputedWidth() - node.yogaNode.getComputedPadding(Yoga.EDGE_LEFT) - node.yogaNode.getComputedPadding(Yoga.EDGE_RIGHT);
+	const columnSizes = resolveTracks(columns, contentWidth, columnGap, columnAutoSizes);
+	const rowSizes = resolveTracks(rows, node.yogaNode.getComputedHeight(), rowGap, rowAutoSizes);
+	const xOffsets = columnSizes.reduce<number[]>((offsets, size) => [...offsets, offsets.at(-1)! + size + columnGap], [node.yogaNode!.getComputedPadding(Yoga.EDGE_LEFT)]);
+	const yOffsets = rowSizes.reduce<number[]>((offsets, size) => [...offsets, offsets.at(-1)! + size + rowGap], [node.yogaNode!.getComputedPadding(Yoga.EDGE_TOP)]);
+	for (const item of placements) {
+		const child = item.child.yogaNode!;
+		child.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		child.setPosition(Yoga.EDGE_LEFT, xOffsets[item.column.start]!);
+		child.setPosition(Yoga.EDGE_TOP, yOffsets[item.row.start]!);
+		child.setWidth(xOffsets[item.column.end]! - xOffsets[item.column.start]! - columnGap);
+		child.setHeight(yOffsets[item.row.end]! - yOffsets[item.row.start]! - rowGap);
+	}
+	if (node.style.height === undefined) node.yogaNode.setHeight(yOffsets.at(-1)! - rowGap + node.yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM));
+};
+
+export const calculateGridLayout = (node: DOMNode): void => {
+	if ('childNodes' in node) {
+		for (const child of node.childNodes) calculateGridLayout(child);
+		layoutGrid(node);
+	}
+};
