const gapFor = (style: Styles, axis: 'column' | 'row'): number =>
	(axis === 'column' ? style.columnGap : style.rowGap) ?? style.gap ?? 0;

const intrinsicHeight = (node: DOMElement): number => {
	if (node.nodeName === 'ink-text')
		return measureText(squashTextNodes(node)).height;

	const height = node.yogaNode?.getComputedHeight() ?? 0;
	if (height > 0) return height;

	return node.childNodes.reduce(
		(maximum, child) =>
			'childNodes' in child
				? Math.max(maximum, intrinsicHeight(child))
				: maximum,
		0,
	);
