const resolveTracks = (
	tracks: Track[],
	available: number,
	gap: number,
	autoSizes: number[],
): number[] => {
	const sizes = tracks.map((track, index) =>
		track.kind === 'fixed'
			? track.size
			: track.kind === 'auto'
